/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { CrustScreen } from "../../src/crust/CrustScreen.js";
import { EarthScreen } from "../../src/earth/EarthScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import PlateTectonicsColors from "../../src/PlateTectonicsColors.js";
import { PlateMotionScreen } from "../../src/plate-motion/PlateMotionScreen.js";
import { PlateTectonicsPreferencesModel } from "../../src/preferences/PlateTectonicsPreferencesModel.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from plateTectonicsQueryParameters.
  const simPreferences = new PlateTectonicsPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new EarthScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().earthStringProperty,
      tandem: Tandem.ROOT.createTandem("earthScreen"),
      backgroundColorProperty: PlateTectonicsColors.backgroundColorProperty,
    }),
    new CrustScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().crustStringProperty,
      tandem: Tandem.ROOT.createTandem("crustScreen"),
      backgroundColorProperty: PlateTectonicsColors.backgroundColorProperty,
    }),
    new PlateMotionScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().plateMotionStringProperty,
      tandem: Tandem.ROOT.createTandem("plateMotionScreen"),
      backgroundColorProperty: PlateTectonicsColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { PlateTectonicsColors, stringManager, simPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
